import{_ as t,a as r}from"./chunks/420465e206eec1b0788b.Cm06VCtf.js";import{_ as o,C as i,o as n,c as l,j as e,a as s,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const y=JSON.parse('{"title":"创作者经济的未来（我的大胆预测）","description":"","frontmatter":{"title":"创作者经济的未来（我的大胆预测）","originalTitle":"The Future Of The Creator Economy (My Bold Prediction)","date":"2023-03-03","originalUrl":"https://thedankoe.com/letters/the-future-of-the-creator-economy-my-bold-prediction/","minutes":12,"sourceHash":"019af24a5f306546c2c7ba28ba80578de9c74adb3f6ba50de2a24596ded09de2","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-future-of-the-creator-economy-my-bold-prediction/"}]]},"headers":[],"relativePath":"letters/the-future-of-the-creator-economy-my-bold-prediction.md","filePath":"letters/the-future-of-the-creator-economy-my-bold-prediction.md"}'),d={name:"letters/the-future-of-the-creator-economy-my-bold-prediction.md"};function m(u,p,f,b,_,g){const a=i("ArticleMeta");return n(),l("div",null,[p[0]||(p[0]=e("h1",{id:"创作者经济的未来-我的大胆预测",tabindex:"-1"},[s("创作者经济的未来（我的大胆预测） "),e("a",{class:"header-anchor",href:"#创作者经济的未来-我的大胆预测","aria-label":'Permalink to "创作者经济的未来（我的大胆预测）"'},"​")],-1)),h(a),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/HR_6nbH4kkk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>复杂的销售漏斗。</p><p>带有倒计时的追加销售。</p><p>荒谬的保证和炫耀庞大的数字。</p><p>租来的兰博基尼，游艇上的美女，为了推销产品而进行<em>付费</em>拍照。</p><p>这就是10年前互联网营销的状况。</p><p>虽然我不认为这一切都很糟糕，但似乎每个人都在如履薄冰，歪曲事实以赚取收入。</p><p><em>“开一家代运营公司，你能快速赚到10万美元。”</em></p><p>就为了让你去学一项你讨厌的技能，去和一群你讨厌的人共事？</p><p><em>“开一家一件代发（dropshipping）网店，你可以直接从中国发货。”</em></p><p>就为了让你去卖无用的产品，为网络上廉价的多巴胺狂欢推波助澜？</p><p><em>“锁定这个细分领域，永远不要跳出来。永远不要进化。永远不要把你的兴趣融入你的工作。永远要尽可能多地榨取客户的钱。”</em></p><p>好吧……没人直接这么说，但在他们所有的教导中都暗示了这一点。</p><p>我其实并不在乎你是否去干这些事。</p><p>但你订阅这份时事通讯，是因为你想要创造更好的生活。</p><p>我在这里要告诉你，有一种方法可以让你靠做自己喜欢的事情谋生，而且随着创作者经济的不断发展，这种方法变得越来越可行。</p><p>前几天，我和我 Modern Mastery 社区的迈克尔（Michael）打了个 Zoom 视频电话，我们对创作者经济的发展趋势进行了一次非常棒的讨论。</p><p>首先，市场的成熟度正在全面提升。</p><p>就像人们对正规教育系统失去信任一样，整个社会集体也正在对过去十年来那些阴暗的营销手段失去信任。</p><h3 id="_1-现实不是相互割裂的" tabindex="-1">1) 现实不是相互割裂的 <a class="header-anchor" href="#_1-现实不是相互割裂的" aria-label="Permalink to &quot;1) 现实不是相互割裂的&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>互联网营销行业走过了与学校教育系统相同的道路。</p><p>常见的建议是尽可能地“深耕细分领域（niche down）”，因为正如他们所说，财富就藏在细分领域中。</p><p>这种说法有其价值，目前仍算得上是半个真理，但一味在目标受众和配套技能上细分下去，就本末倒置了。</p><p>为了从<em>一个目标、伴随的问题以及获取跨越鸿沟的技能</em>这个角度去定位而进行细分，则是另一回事。</p><p>营销的本质是通过独特的解决方案来交付一种转变。</p><p>你用一套能出结果的系统，帮助人们从A点走到B点。</p><p>在学校系统中，有各个独立的院系，帮助你在不同的“口袋”（隔离的小块）里进行“学习”。</p><p>比如化学、生物学、商业、设计或建筑学。</p><p>这种结构忽视了事物间相互联系的本质，而这种本质本可以让你学得快得多。</p><p>就像海洋化为雨滴，最终又重新汇聚回海洋一样，互联网营销领域也遵循着同样的进化模式。</p><p>它曾分裂成一个个细分的独立隔间，如今又重新融合为对整体、统一解决方案的需求。</p><h3 id="_2-为拥有共同目标的社区提供整体解决方案" tabindex="-1">2) 为拥有共同目标的社区提供整体解决方案 <a class="header-anchor" href="#_2-为拥有共同目标的社区提供整体解决方案" aria-label="Permalink to &quot;2) 为拥有共同目标的社区提供整体解决方案&quot;">​</a></h3><p>拿破仑·希尔（Napoleon Hill）有一个概念，他称之为“智囊团（Master Mind）”。</p><p>简而言之，它是一群因拥有共同视角而相互吸引的人。</p><p>一个视角是由一个目标（目的）及相伴随的信念组成的。</p><p>当一群人或一个社区为了实现同一个目的而聚集在一起时，他们实现目的的速度能比任何单打独斗的个人快10倍。</p><p>谈到创作者经济，个体正在吸引一个与他们的目标、声音和个性产生共鸣的社区群体。</p><p>然后，这些创作者们提供与众多技能和兴趣相关的教育，以帮助实现这一目标。</p><p>就像 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> 吸引了特定的一群人，他们与我“少工作、多赚钱、享受生活”这一有意义的目标产生了共鸣。</p><p>那个目标并不局限于某一个细分领域或兴趣。</p><p>它是实现该目标所需一切事物的整体综合。</p><p>思想、身体、精神和商业，以及帮助改善每一项的策略。</p><p>我们需要更少肤浅的承诺，以及更多能够达成有意义目标的解决方案。</p><p>大多数现代商业模式都做不到这一点。</p><p>做一件代发卖个花哨的小手电筒没有任何深度可言。</p><p>为了赚点快钱去搞个按需打印的简陋日记本，毫无灵魂。</p><p>用你讨厌的技能开一家代运营公司，去服务你讨厌的客户画像，只会导致肤浅的工作。</p><h3 id="_3-清晰度高于一切" tabindex="-1">3) 清晰度高于一切 <a class="header-anchor" href="#_3-清晰度高于一切" aria-label="Permalink to &quot;3) 清晰度高于一切&quot;">​</a></h3><p>过去十年的互联网营销依赖于复杂性。</p><p>产品和服务本来都具有同样简单的解决方案，但它们的营销方式却把里面的内容过度复杂化了（为了提高产品的感知价值）。</p><p>如今，人们想要一种清晰、简单、直接的解决方案，并且是以<em>他们学得最好</em>的<em>视角来教授</em>的。</p><p>有些人非常务实。</p><p>我则很有哲理，而我的受众群体也反映了这一点。</p><p>通过倾向于<em>你</em>最容易吸收学习的声音，你就能吸引来与你有共同目标、且最能从你这里学到东西的人。</p><p>这就开始勾勒出我那句话背后的深度了：“<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">你就是细分领域</a>”。</p><h2 id="整体整合者的出现与需求" tabindex="-1">整体整合者的出现与需求 <a class="header-anchor" href="#整体整合者的出现与需求" aria-label="Permalink to &quot;整体整合者的出现与需求&quot;">​</a></h2><p>在这种哲学理念下，创作者经济是不可能饱和的，因为：</p><p><strong>1) 你的社区在进化</strong></p><p>当你不盲从于限制你能力的特定标签、细分领域或现实的独立隔间时，你唯一的选择就是进化。</p><p>人类和社区不会永远固守一个目的。</p><p>一旦你实现了那个目标，你就会走向下一个显现出来的目标。</p><p><strong>2) 你的产品在进化</strong></p><p>我最初是做网页设计师起家的，我的产品和服务都是围绕这一点展开的。</p><p>随着我发展自我和我的业务，我过渡到了不同的技能和兴趣上。</p><p>我的产品也紧随其后，实际上，我成功地为自己手底下的网页设计市场“去饱和化”了。</p><p><strong>3) 独特的兴趣网络</strong></p><p>当你倾注于你真正感兴趣的组合时，你的品牌就不再是割裂的。</p><p>一个谈论健身、商业和科技的人，与一个谈论健身、商业和灵性的人依然有着天壤之别。</p><p><strong>4) 大型创作者拥有充足的资源</strong></p><p>大型创作者在各条战线上减少产出，这并不罕见。</p><p>去看看那些拥有超过100万订阅者的 YouTuber 吧。</p><p>大约有50%的情况下，你会发现他们几乎不再发内容，或者彻底停止更新了。</p><p>Twitter 上的创作者也是如此。那些大号的发布频率往往会降到每周几次。</p><p>这就给了新晋创作者涌入市场、吸引更多关注、并建立人脉和资源的能力，而且没有太多来自“大玩家”的竞争压力。</p><p>大玩家们则会继续追求新的目标，比如组建家庭，或者利用他们现在拥有的杠杆建立一家独立的公司。</p><h3 id="对深度的需求" tabindex="-1">对深度的需求 <a class="header-anchor" href="#对深度的需求" aria-label="Permalink to &quot;对深度的需求&quot;">​</a></h3><p>我们的创作者经济已经到了一个临界点。</p><p>内容平台上已经充斥着为了增长而制造的那些基础、肤浅、被咀嚼过无数次的陈词滥调。</p><p>这未必是坏事，而且仍然能够涨粉，但我的问题是……为什么？</p><ul><li>为什么要将想法过度系统化？</li><li>为什么要剥夺你事业的灵魂？</li><li>为什么要将增长、收入和浅薄的影响力置于一切之上？</li><li>为什么要限制那个唯一能让你作为个体脱颖而出的东西：你的创造力？</li></ul><p>整个领域的普遍认知水平正在提升。</p><p>市场将会要求创作者们超越泛泛的引语，以及那些老掉牙的一步步自助建议。</p><p>只有当你把深度、视角和整体整合放在首位时，你才能做到这一点。</p><h3 id="整体整合者" tabindex="-1">整体整合者 <a class="header-anchor" href="#整体整合者" aria-label="Permalink to &quot;整体整合者&quot;">​</a></h3><p>让我们来定义一下什么是“整体整合者”：</p><p><em>追寻自己的愿景，用自己</em> <em>获取__的独特技能和兴趣开辟出属于自己道路的人。<strong>他们不把这些技能或兴趣视为孤立的部分，而是视为生活中不可或缺且相互关联的整体（而不是为了赚快钱的临时拼凑）</strong>。<strong>他们毕生的工作，就是在这条道路上提炼、传授并传播他们的个人经验</strong>。</em></p><p>简而言之，整体整合者就是一个以具有说服力和教育意义的方式，记录下自己对美好生活追求过程的人。</p><p>这样一来，你就能吸引到与你声音产生共鸣的社区，帮助他们实现共同的目标，且不会将自己局限在现实中某个被割裂的孤岛里。</p><ul><li><strong>你的品牌就是你的故事</strong> – 不论经验多寡，呈现你现在的状态。</li><li><strong>你的内容就是你的学校</strong> – 传授是何种事物帮助你走到了今天。</li><li><strong>你的产品就是那张地图</strong> – 一个整体的系统，帮助人们用更少的试错成本到达你现在的位置。</li></ul><p>互联网赋予了你自我教育的力量，其速度比以往任何人类所能达到的都要快得多。</p><p>主动承担起改善自己生活的责任，追寻你的好奇心，分享你的发现。</p><p>还有什么比这更好的事情可做吗？</p><p>在你跑去创立一家价值十亿美元的科技公司之前，考虑先从唯一重要的事情开始做起：</p><p><em>改善全人类为了进化都必须改善的一件事：他们的人类体验的质量。</em></p><p>当更多的人掌控了自己的个人生活时，他们就能把大脑中的创造力汇聚在一起，致力于解决全球性问题。</p><p>当你做到这一点时，你自然会知道下一步该怎么做。</p><p>你将成为一个去开拓新路径的大型创作者，并为你手底下的市场去饱和化。</p><h2 id="一种新的生活方式" tabindex="-1">一种新的生活方式 <a class="header-anchor" href="#一种新的生活方式" aria-label="Permalink to &quot;一种新的生活方式&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>创作者的哲学不是一种商业模式，而是一种生活方式。</p><p>提升自己 &gt; 提升其他想要得到帮助的人。</p><p>你可以从今天起就开始采取以下步骤：</p><h3 id="_1-掌控你的生存" tabindex="-1">1) 掌控你的生存 <a class="header-anchor" href="#_1-掌控你的生存" aria-label="Permalink to &quot;1) 掌控你的生存&quot;">​</a></h3><p>当你<em>需要</em>从别人那里得到什么时，你是无法保持真实的。</p><p>地球上的每一个个体都必须自我实现，才能以最好的方式为全人类做出贡献。</p><p><strong>自我实现（Self-actualization）：</strong><em>满足成为自己所能成为的一切的渴望。去实现你的潜能。</em></p><p>虽然这可以通过一条完美的职业道路来实现，但这并非我能帮上忙的领域。而且，那也不是你能完全掌控的事情。</p><p>创业就是现代的生存方式。</p><p>我们猎取资源（现代意义上的金钱），来满足我们的需求并<em>创造</em>我们享受的工作。如果我们不喜欢其中的某些方面，商业模式允许你消除、委派或自动化那一部分的工作。</p><p>我的建议依然不变：</p><ul><li>解决你生活中的生物性问题</li><li>改善你的健康、财务和社交</li><li>在改善的过程中发现你的兴趣</li></ul><p>这需要时间，但这并不妨碍你打造一份独立的收入来源。</p><p>95%的人的问题都围绕着健康、财富、人际关系和幸福。</p><p>如果你能解决自己生活中的这些问题，并把解决方案记录下来，你就可以为你所获取的知识收费。</p><p>对于个体来说，向领先自己10步的人学习并不是效果最好的，向领先自己1步的人学习才是。</p><h3 id="_2-创造你自己的哲学" tabindex="-1">2) 创造你自己的哲学 <a class="header-anchor" href="#_2-创造你自己的哲学" aria-label="Permalink to &quot;2) 创造你自己的哲学&quot;">​</a></h3><p>关于如何赚钱、如何上床，以及如何用各种“创可贴”去敷衍心理健康的肤浅建议已经够多了。</p><p>我们需要更多追求真理的个体。</p><p>那些明白按部就班的建议表面上看起来不错、但内里空洞无物的个体。</p><p>我们需要更多直击问题根源的人，这些根源往往是形而上学的、精神的，或者认识论的。</p><p>这个世界极其渴望深度，而这只能通过开辟你自己的道路来创造。</p><p>哲学是基于经验的。</p><p>你必须把心思放在一个理想的未来上，全心全意地去追求它，犯错，并纠正你的行动。</p><p>我们来这里不是为了得到几十年来其他人都在得到的同样的结果。</p><p>举个例子，我理想的未来是每天工作4小时，在空闲时间做我想做的事，并帮助别人实现一种更好的生活方式。</p><p>我的哲学是由那些最让我产生共鸣的导师们所激发的。</p><p>我啃完了一本又一本关于心理学、哲学、现代工作和现代休息的书，通过经验来完善我的哲学。</p><h3 id="_3-将其变成一所公共学校" tabindex="-1">3) 将其变成一所公共学校 <a class="header-anchor" href="#_3-将其变成一所公共学校" aria-label="Permalink to &quot;3) 将其变成一所公共学校&quot;">​</a></h3><p>我坚信未来的学校教育将在线上进行，由创作者担任教师，每个学生都可以加入最符合他们兴趣、价值观和偏好学习方式的“学校”。</p><p><em>单一的学校系统将不再主宰他们12年以上的生命。</em></p><p>几年后，学生们将在以创作者为基础的“学校”中进化超越，然后进入下一所学校，如果其他学校具备批判性思维和个人经验的基本原则，他们最终甚至能够创办自己的学校。</p><p>把创建知识库作为你毕生的事业，在你的品牌或学校名下将其分享到网上，并用一种潜在的哲学来吸引对的人。</p><p>你的公共学校就是数字房地产。</p><p>用推特（Twitter）、Instagram和领英（LinkedIn）来吸引广泛的受众。</p><p>用YouTube、播客，以及博客或时事通讯来教育和培养受众。</p><p>还有一系列的产品，从低价课程、会员订阅到高价的定制教练服务。</p><p>这就是我倾注心血去教授的东西，因为我看到了这个领域的机遇。</p><p>所以，我提供了 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时写手 (2 Hour Writer)</a> 来帮助人们在没有经验的情况下把他们的想法表达出来。</p><p>然后，我提供了一个更昂贵的大师班，<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学 (Digital Economics)</a>，帮助那些真心想把这件事做成的人将自己产品化。</p><p>最终，你将获得资源去创办任何你想要的业务，以进一步传播你的信息。</p><h3 id="_4-打造一个整体解决方案" tabindex="-1">4) 打造一个整体解决方案 <a class="header-anchor" href="#_4-打造一个整体解决方案" aria-label="Permalink to &quot;4) 打造一个整体解决方案&quot;">​</a></h3><p>我曾与5000多名创作者合作过，主要问题之一是不知道卖什么，或者不知道如何让卖的东西独一无二。</p><p>我将在下一封信中充实我的“最小可行报价（Minimum Viable Offer）”策略。</p><p>这将帮助你从0开始。</p><p>我特别喜欢创建一个目前这个领域还没人做过的“辅导”报价。我将向你展示如何创建一个。</p><p>在那之前，你先这么做：</p><p><strong>1) 确定一个令人向往的目标</strong></p><p>你生活中正在努力实现、或者已经实现的一个大目标是什么？</p><p>你身材好吗？你掌握了一门技能（比如写作）吗？你理解了现实的本质吗？它到底是什么？你完成了什么，无论你觉得它有多小或多么微不足道？</p><p>这其中的关键在于：</p><p>不要把注意力放在目标本身，而是要关注它为你创造的生活方式。</p><p><strong>2) 确定你的起点</strong></p><p>是什么让你想要改变？</p><p>你生活中火烧眉毛的问题是什么？</p><p>在实现这个目标之前，你的生活是什么样的？</p><p>营销就是关于转变。</p><p>你是在帮助别人从A点（你曾经所在的位置）走到B点（令人向往的目标）。</p><p><strong>3) 勾勒出一条独特的道路</strong></p><p>现在，勾勒出从A点到B点所必需的模块、章节或步骤。</p><p>你现在正处于人生的某个节点，你可以回头看看，并帮助其他人避开你曾犯过的错误。</p><p>就像你在列一本书的大纲一样。</p><p>填空，写下人们为了达到目标需要知道什么、学习什么、做什么。</p><p>现在就开始思考这个问题，我们将在下一封信中回到这一点。</p><h3 id="_5-拓展新机遇" tabindex="-1">5) 拓展新机遇 <a class="header-anchor" href="#_5-拓展新机遇" aria-label="Permalink to &quot;5) 拓展新机遇&quot;">​</a></h3><p>随着你作为一个创作者开始、成长和进化，你将达到呈现新机遇的发展阶段。</p><p>也许你会全职做播客。</p><p>也许你会写一本书（我现在正在写）。</p><p>也许你会开发一款软件（我现在正在开发）。</p><p>最困难的部分是在头一年左右在市场上站稳脚跟。</p><p>之后，你的观点和名字已经传达给了如此多的人，以至于你不可能输。</p><p>这期就到这里。</p><p>下周聊，</p><p>– Dan</p><hr><p><a href="/en/letters/the-future-of-the-creator-economy-my-bold-prediction">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',176))])}const x=o(d,[["render",m]]);export{y as __pageData,x as default};
